-- Ephemeral fixtures only. No real credentials, provider traffic or generated content.
begin;
create temporary table mf(actor uuid,viewer uuid,wid uuid,sid uuid,profile uuid,request uuid,claim uuid,op uuid,doc jsonb);
insert into mf values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null);
insert into auth.users(id) select actor from mf union all select viewer from mf;
insert into public.bizoveya_workspaces(id,owner_id,name) select wid,actor,'Media fixture' from mf;
insert into public.bizoveya_memberships(workspace_id,user_id,role) select wid,actor,'owner' from mf union all select wid,viewer,'viewer' from mf;
insert into public.bizoveya_sites(id,workspace_id,name,mode,kind,status,created_by) select sid,wid,'Media site','native_business','business','active',actor from mf;
select bizoveya_private.set_platform_admin(actor,true,'fixture','Synthetic media operator') from mf;
update bizoveya_private.model_credentials set enabled=true where id='platform-gemini';
insert into bizoveya_private.model_profiles(id,slug,version,revision) select profile,'media-fixture',1,1 from mf;
insert into bizoveya_private.model_profile_versions(profile_id,version,document,reason) select profile,1,'{"name":"Fixture Gemini","provider":"gemini","credentialRef":"platform-gemini","modelId":"fixture-model","tier":"economical","maxOutputTokens":1500,"dailyBudgetCents":100}','Synthetic media fixture' from mf;
insert into bizoveya_private.model_profile_checks(profile_id,version,credential_id,credential_version) select profile,1,'platform-gemini',1 from mf;
insert into bizoveya_private.spending_policies(profile_id,version,profile_version,document,reason) select profile,1,1,jsonb_build_object('enabled',true,'inputRateMicros',1000000,'outputRateMicros',1000000,'requestFeeMicros',0,'dailyLimitMicros',100000,'runLimitMicros',10000,'validUntil',clock_timestamp()+interval '7 days','source','https://example.com/fictional-pricing','reviewed',true),'Synthetic reviewed prices' from mf;
update mf set doc=jsonb_build_object('provider','gemini','modelId','fixture-model','credentialRef','platform-gemini','credentialVersion',1,'budgetProfileId',profile,'costMode','metered','inputTokenLimit',256,'outputTokenLimit',128,'durationSeconds',60,'maxDailyRequests',20,'maxConcurrent',1,'inputRateMicros',1000000,'outputRateMicros',1000000,'requestFeeMicros',0,'validUntil',clock_timestamp()+interval '1 day','evidenceUrl','https://example.com/synthetic-api-evidence','apiVerified',true,'commercialReviewed',true);
create function pg_temp.expect(q text,n text) returns void language plpgsql as $$begin begin execute q;exception when others then if strpos(sqlerrm,n)>0 then return;end if;raise;end;raise exception 'Expected %',n;end;$$;
create function pg_temp.review(cap text default 'image',ver integer default 0) returns jsonb language sql as $$select jsonb_build_object('operationId',op,'capability',cap,'expectedVersion',ver,'action','qualify','reason','Synthetic API and pricing evidence only.','reviewed',true,'document',doc) from mf$$;
create function pg_temp.admit(cap text default 'image',ver integer default 1) returns jsonb language sql as $$select jsonb_build_object('id',request,'capability',cap,'expectedQualificationVersion',ver,'document',case when cap='image' then '{"prompt":"A synthetic private test illustration","aspectRatio":"1:1"}'::jsonb else '{"purpose":"founder-assistant"}'::jsonb end,'reviewed',true) from mf$$;
do $$begin execute format('grant usage on schema %I to authenticated,service_role',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end;$$;grant all on mf to authenticated,service_role;
set local role authenticated;select set_config('request.jwt.claim.sub',(select actor::text from mf),true);
select set_config('request.jwt.claims','{"aal":"aal1"}',true);
select pg_temp.expect(format('select public.bz_admin_review_media_capability(%L,%L,%L)',wid,sid,pg_temp.review()),'bz_mfa_required') from mf;
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select pg_temp.expect(format('select public.bz_admit_media_request(%L,%L,%L)',wid,sid,pg_temp.admit()),'bz_media_unqualified') from mf;
select pg_temp.expect(format('select public.bz_admin_review_media_capability(%L,%L,%L)',wid,sid,pg_temp.review()||jsonb_build_object('document',doc||jsonb_build_object('costMode','free-attested'))),'bz_invalid_media_capability') from mf;
select public.bz_admin_review_media_capability(wid,sid,pg_temp.review()) from mf;
select public.bz_admin_review_media_capability(wid,sid,pg_temp.review()) from mf; -- exact operation replay
select pg_temp.expect(format('select public.bz_admin_review_media_capability(%L,%L,%L)',wid,sid,pg_temp.review()||'{"reason":"Changed operation content conflicts."}'::jsonb),'bz_conflict') from mf;
select pg_temp.expect(format('select public.bz_admit_media_request(%L,%L,%L)',wid,sid,pg_temp.admit('image',2)),'bz_conflict') from mf;
select set_config('request.jwt.claim.sub',(select viewer::text from mf),true);
select public.bz_media_inventory(wid,sid) from mf;
select pg_temp.expect(format('select public.bz_admit_media_request(%L,%L,%L)',wid,sid,pg_temp.admit()),'bz_forbidden') from mf;
select set_config('request.jwt.claim.sub',(select actor::text from mf),true);
select public.bz_admit_media_request(wid,sid,pg_temp.admit()) from mf;
do $$declare v jsonb;begin select public.bz_admit_media_request(wid,sid,pg_temp.admit()) into v from mf;if v->'execute' is distinct from 'false'::jsonb or v ?| array['snapshot','command','claim','token'] then raise exception 'Unsafe admission replay';end if;end;$$;
select pg_temp.expect(format('select public.bz_admit_media_request(%L,%L,%L)',wid,sid,pg_temp.admit()||jsonb_build_object('id',gen_random_uuid())),'bz_media_concurrency') from mf;
select pg_temp.expect(format('select public.bz_claim_media_request(%L,%L,%L)',request,claim,actor),'permission denied') from mf;
select pg_temp.expect('select * from bizoveya_private.media_requests','permission denied');
reset role;
set local role service_role;
select pg_temp.expect(format('select public.bz_claim_media_request(%L,%L,%L)',request,claim,viewer),'bz_forbidden') from mf;
select public.bz_claim_media_request(request,claim,actor) from mf;
do $$declare v jsonb;begin select public.bz_claim_media_request(request,claim,actor) into v from mf;if v->'execute' is distinct from 'false'::jsonb then raise exception 'Repeated claim can execute';end if;end;$$;
select public.bz_cancel_unstarted_media_request(request,actor) from mf;
reset role;
do $$begin if exists(select 1 from bizoveya_private.media_requests where status<>'cancelled' or charged_micros<>0 or provider_started_at is not null) then raise exception 'Unstarted cancellation contract';end if;end;$$;
update mf set request=gen_random_uuid(),claim=gen_random_uuid();
set local role authenticated;select public.bz_admit_media_request(wid,sid,pg_temp.admit()) from mf;reset role;
set local role service_role;select public.bz_claim_media_request(request,claim,actor) from mf;
select public.bz_start_media_provider(request,claim,actor) from mf;
select pg_temp.expect(format('select public.bz_start_media_provider(%L,%L,%L)',request,claim,actor),'bz_conflict') from mf;
select pg_temp.expect(format('select public.bz_cancel_unstarted_media_request(%L,%L)',request,actor),'bz_media_provider_started') from mf;
select public.bz_finish_media_request(request,claim,false,null,null,null,'provider_failed') from mf;reset role;
do $$begin if not exists(select 1 from bizoveya_private.media_requests where spending_state='unknown' and charged_micros=reserved_micros and provider_started_at is not null) then raise exception 'Unknown usage lost reservation';end if;end;$$;
set local role authenticated;
select pg_temp.expect(format('select public.bz_admit_media_request(%L,%L,%L)',wid,sid,pg_temp.admit()||jsonb_build_object('id',gen_random_uuid())),'bz_spending_unresolved') from mf;
select pg_temp.expect(format('select public.bz_admin_begin_model_test(%L,%L,1,1,%L,true,%L)',gen_random_uuid(),profile,gen_random_uuid(),'Reviewed synthetic connectivity request.'),'bz_spending_unresolved') from mf;
select public.bz_admin_recover_media_request(request,'unknown','reconcile',0,'Synthetic zero-cost evidence reconciled.',true) from mf;
select pg_temp.expect(format('select public.bz_admin_recover_media_request(%L,%L,%L,0,%L,true)',request,'unknown','reconcile','Synthetic repeated reconciliation.'),'bz_conflict') from mf;
reset role;
update mf set request=gen_random_uuid(),claim=gen_random_uuid();
set local role authenticated;select public.bz_admit_media_request(wid,sid,pg_temp.admit()) from mf;reset role;
set local role service_role;select public.bz_claim_media_request(request,claim,actor) from mf;select public.bz_start_media_provider(request,claim,actor) from mf;
select pg_temp.expect(format('select public.bz_finish_media_request(%L,%L,true,20,20,%L,null)',request,claim,'{}'),'bz_invalid_media_result') from mf;
select pg_temp.expect(format('select public.bz_finish_media_request(%L,%L,true,20,20,%L,null)',request,claim,jsonb_build_object('artifactHash',repeat('a',64))),'bz_invalid_media_result') from mf;
select public.bz_finish_media_request(request,claim,true,300,20,jsonb_build_object('artifactHash',repeat('a',64),'mime','image/png'),null) from mf;reset role;
do $$begin if not exists(select 1 from bizoveya_private.media_requests where spending_state='overrun' and input_tokens=300) then raise exception 'Overrun not retained';end if;end;$$;
set local role authenticated;select public.bz_admin_recover_media_request(request,'overrun','reconcile',320,'Synthetic metered charge confirmed.',true) from mf;reset role;
update mf set request=gen_random_uuid(),claim=gen_random_uuid(),op=gen_random_uuid();
set local role authenticated;select public.bz_admin_review_media_capability(wid,sid,pg_temp.review('live-voice')) from mf;
select public.bz_admit_media_request(wid,sid,pg_temp.admit('live-voice')) from mf;reset role;
set local role service_role;select public.bz_claim_media_request(request,claim,actor) from mf;select public.bz_start_media_provider(request,claim,actor) from mf;
select public.bz_finish_media_request(request,claim,true,null,null,jsonb_build_object('tokenExpiresAt',clock_timestamp()+interval '30 seconds'),null) from mf;
select pg_temp.expect(format('select public.bz_finish_media_request(%L,%L,true,0,0,null,null)',request,claim),'bz_media_session_active') from mf;reset role;
do $$begin if not exists(select 1 from bizoveya_private.media_requests where status='issued' and spending_state='reserved' and input_tokens is null) then raise exception 'Token issuance falsely settled';end if;end;$$;
update bizoveya_private.media_requests set expires_at=statement_timestamp()-interval '1 second' where capability='live-voice';
set local role authenticated;select public.bz_admin_recover_media_request(request,'reserved','recover',null,'Synthetic expired session with unknown usage.',true) from mf;reset role;
set local role authenticated;select public.bz_admin_recover_media_request(request,'unknown','reconcile',0,'Synthetic expired session charge confirmed.',true) from mf;reset role;
-- Qualification changes are rechecked before provider start, not just on admission.
update mf set request=gen_random_uuid(),claim=gen_random_uuid(),op=gen_random_uuid();
set local role authenticated;
select public.bz_admit_media_request(wid,sid,pg_temp.admit()) from mf;
select public.bz_admin_review_media_capability(wid,sid,jsonb_build_object('operationId',op,'capability','image','expectedVersion',1,'action','pause','reason','Synthetic emergency capability pause.','reviewed',true)) from mf;
reset role;set local role service_role;
select pg_temp.expect(format('select public.bz_claim_media_request(%L,%L,%L)',request,claim,actor),'bz_media_unqualified') from mf;
select public.bz_cancel_unstarted_media_request(request,actor) from mf;reset role;
update mf set op=gen_random_uuid(),request=gen_random_uuid(),claim=gen_random_uuid();
update mf set doc=jsonb_set(doc,'{maxDailyRequests}','1');
set local role authenticated;
select public.bz_admin_review_media_capability(wid,sid,pg_temp.review('image',1)) from mf;
select pg_temp.expect(format('select public.bz_admit_media_request(%L,%L,%L)',wid,sid,pg_temp.admit('image',2)),'bz_media_daily_quota') from mf;
reset role;
-- Old request usage can become unresolved between new media admission and provider start.
update mf set op=gen_random_uuid(),request=gen_random_uuid(),claim=gen_random_uuid();
update mf set doc=jsonb_set(doc,'{maxDailyRequests}','20');
set local role authenticated;select public.bz_admin_review_media_capability(wid,sid,pg_temp.review('image',2)) from mf;
select public.bz_admit_media_request(wid,sid,pg_temp.admit('image',3)) from mf;reset role;
-- Fixture legacy connectivity ledger, not a provider call.
alter table mf add column legacy uuid default gen_random_uuid();
insert into bizoveya_private.model_test_runs(id,profile_id,profile_version,credential_id,credential_version,claim,status,result_code,reason,finished_at) select legacy,profile,1,'platform-gemini',1,gen_random_uuid(),'failed','provider_error','Synthetic unresolved old connectivity request',clock_timestamp() from mf;
insert into bizoveya_private.spending_ledger(run_id,profile_id,policy_version,policy_snapshot,state,reserved_micros,charged_micros) select legacy,profile,1,'{}','unknown',10,10 from mf;
set local role service_role;
select pg_temp.expect(format('select public.bz_claim_media_request(%L,%L,%L)',request,claim,actor),'bz_spending_unresolved') from mf;reset role;
update bizoveya_private.spending_ledger set state='reconciled',charged_micros=0 where run_id=(select legacy from mf);
set local role service_role;select public.bz_claim_media_request(request,claim,actor) from mf;reset role;
update bizoveya_private.spending_ledger set state='unknown' where run_id=(select legacy from mf);
set local role service_role;
select pg_temp.expect(format('select public.bz_start_media_provider(%L,%L,%L)',request,claim,actor),'bz_spending_unresolved') from mf;
select public.bz_cancel_unstarted_media_request(request,actor) from mf;reset role;
update bizoveya_private.spending_ledger set state='reconciled',charged_micros=0 where run_id=(select legacy from mf);
-- A media charge is included in the existing shared UTC daily budget.
update bizoveya_private.media_requests set spending_state='reconciled',charged_micros=100001 where capability='live-voice';
set local role authenticated;
select pg_temp.expect(format('select public.bz_admin_begin_model_test(%L,%L,1,1,%L,true,%L)',gen_random_uuid(),profile,gen_random_uuid(),'Synthetic shared daily budget review.'),'bz_daily_budget') from mf;
reset role;
-- Immutable lineage and audit events.
select pg_temp.expect(format('update bizoveya_private.media_requests set request_hash=%L where id=%L',repeat('b',64),(select id from bizoveya_private.media_requests limit 1)),'bz_immutable_media_request') from mf;
select pg_temp.expect('update bizoveya_private.media_request_events set action=''changed''','bz_immutable');
do $$begin if has_function_privilege('anon','public.bz_admit_media_request(uuid,uuid,jsonb)','EXECUTE') or has_function_privilege('authenticated','public.bz_start_media_provider(uuid,uuid,uuid)','EXECUTE') then raise exception 'Unsafe RPC grants';end if;end;$$;
select public.bz_media_inventory(wid,sid) as contract071 from mf;
rollback;
